css:
.sl-team-courses {
    position: relative;
    padding-block: clamp(3rem, 6vw, 5rem);
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-team-courses .sl-ic-showcase {
    display: flex;
    flex-direction: column;
    gap: 3rem;
    max-width: 1100px;
    margin: 0 auto;
}

@media (min-width: 992px) {
    .sl-team-courses .sl-ic-showcase {
        flex-direction: row;
        gap: 5rem;
    }
}

/* Instructor Column */
.sl-team-courses .sl-instructor-col {
    flex: 0 0 300px;
}

.sl-team-courses .sl-instructor-sticky {
    position: sticky;
    top: calc(var(--smartlearn-navbar-height, 64px) + 1.5rem);
    text-align: center;
}

.sl-team-courses .sl-instructor-img {
    width: 200px;
    height: 200px;
    border-radius: 50%;
    object-fit: cover;
    object-position: center top;
    margin: 0 auto 1.5rem;
    border: 4px solid var(--smartlearn-card-bg);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.sl-team-courses .sl-instructor-name {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: 1.75rem;
    font-weight: 800;
    color: var(--smartlearn-text);
    margin-bottom: 0.5rem;
}

.sl-team-courses .sl-instructor-role {
    font-size: 1rem;
    color: var(--smartlearn-text-muted);
    margin-bottom: 2rem;
}

.sl-team-courses .sl-instructor-stats {
    display: flex;
    justify-content: center;
    gap: 1.5rem;
    margin-bottom: 2rem;
    padding: 1.5rem 0;
    border-top: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
    border-bottom: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
}

.sl-team-courses .sl-stat {
    display: flex;
    flex-direction: column;
}

.sl-team-courses .sl-stat-val {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--smartlearn-text);
}

.sl-team-courses .sl-stat-lbl {
    font-size: 0.75rem;
    color: var(--smartlearn-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* Courses Column */
.sl-team-courses .sl-ic-col {
    flex: 1;
    min-width: 0;
}

.sl-team-courses .sl-ic-header {
    border-bottom: 2px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
    margin-bottom: 2rem;
    padding-bottom: 1rem;
}

.sl-team-courses .sl-ic-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--smartlearn-text);
    margin: 0;
}

.sl-team-courses .sl-ic-list {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    margin-bottom: 2.5rem;
}

.sl-team-courses .sl-ic-card {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
    border-radius: var(--smartlearn-radius, 1rem);
    padding: 1rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.sl-team-courses .sl-ic-card:hover {
    transform: translateX(5px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.06);
}

[dir="rtl"] .sl-team-courses .sl-ic-card:hover {
    transform: translateX(-5px);
}

.sl-team-courses .sl-ic-img-wrap {
    flex: 0 0 100px;
    height: 80px;
    border-radius: calc(var(--smartlearn-radius, 1rem) * 0.5);
    overflow: hidden;
    background-color: color-mix(in srgb, var(--smartlearn-text) 6%, transparent);
}

.sl-team-courses .sl-ic-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.sl-team-courses .sl-ic-info {
    flex: 1;
    min-width: 0;
}

.sl-team-courses .sl-ic-name {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--smartlearn-text);
    margin-bottom: 0.25rem;
}

.sl-team-courses .sl-ic-meta {
    font-size: 0.875rem;
    color: var(--smartlearn-text-muted);
    margin-bottom: 0.5rem;
}

.sl-team-courses .sl-ic-link {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--smartlearn-primary);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    border-radius: 0.25rem;
}

.sl-team-courses .sl-ic-link:hover {
    text-decoration: underline;
}

.sl-team-courses .sl-ic-link:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

[dir="rtl"] .sl-team-courses .sl-ic-arrow {
    transform: scaleX(-1);
}

.sl-team-courses .sl-ic-footer {
    text-align: end;
}

/* Buttons */
.sl-team-courses .sl-btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    border-radius: var(--smartlearn-radius, 0.5rem);
    font-weight: 600;
    font-size: 1rem;
    text-decoration: none;
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.sl-team-courses .sl-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

.sl-team-courses .sl-btn-outline {
    background-color: transparent;
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.2));
    color: var(--smartlearn-text);
}

.sl-team-courses .sl-btn-outline:hover {
    background-color: color-mix(in srgb, var(--smartlearn-text) 8%, transparent);
    border-color: var(--smartlearn-text);
}

.sl-team-courses .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    border: 1px solid var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}

.sl-team-courses .sl-btn-primary:hover {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
}

@media (max-width: 575px) {
    .sl-team-courses .sl-ic-card {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }
    .sl-team-courses .sl-ic-img-wrap {
        flex: 0 0 auto;
        width: 100%;
        height: 160px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .sl-team-courses .sl-ic-card,
    .sl-team-courses .sl-btn {
        transition: none;
    }
    .sl-team-courses .sl-ic-card:hover,
    [dir="rtl"] .sl-team-courses .sl-ic-card:hover {
        transform: none;
    }
}
